css:
:root:not(.dark) svg.lucide {
  stroke-width: 1.75;
  stroke-linecap: square;
  stroke-linejoin: miter;
}
:root:not(.dark) [data-chat-header] {
  background-image: linear-gradient(90deg, #18496B, #AD3D0A);
  background-size: 100% 2px;
  background-position: 0 100%;
  background-repeat: no-repeat;
}
:root:not(.dark) [data-slot='composer-host']:focus-within {
  border-color: #AD3D0A;
  box-shadow: 0 0 0 1px #AD3D0A;
}
:root:not(.dark) [data-slot='scroll-area-thumb'] {
  background-color: #6E768266;
  border-radius: 2px;
}
:root:not(.dark) [data-slot='scroll-area-thumb']:hover {
  background-color: #6E7682AA;
}
:root:not(.dark) ::selection {
  background-color: #C6DAEB;
  color: #0D1016;
}
:root:not(.dark) input,
:root:not(.dark) textarea,
:root:not(.dark) .composer-tiptap {
  caret-color: #AD3D0A;
}
:root:not(.dark) [data-thread-item][data-active='true'],
:root:not(.dark) [data-thread-item][aria-current='page'] {
  box-shadow: inset 2px 0 0 0 #AD3D0A;
}
